package net.civeira.phylax.feature.observe.observedprobe.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedprobe.domain.ObservedProbe;
import net.civeira.phylax.feature.observe.observedprobe.domain.valueobject.TimeoutMsVO;

class TimeoutMsValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of timeout ms of observed probe")
  void test_timeout_ms_value_holder_assign_plain_value() {
    Object holder = new Object();
    TimeoutMsValueHolder<Object> value = new TimeoutMsValueHolder<>(holder);
    Assertions.assertSame(holder, value.timeoutMs(1), "Setters must return the holder");
    Assertions.assertTrue(value.getTimeoutMsValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals(1, value.getTimeoutMs().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of timeout ms of observed probe")
  void test_timeout_ms_value_holder_assign_value_object() {
    Object holder = new Object();
    TimeoutMsValueHolder<Object> value = new TimeoutMsValueHolder<>(holder);
    TimeoutMsVO vo = TimeoutMsVO.from(1);
    Assertions.assertFalse(value.getTimeoutMsValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.timeoutMs(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getTimeoutMsValue().orElseThrow());
    Assertions.assertSame(holder, value.timeoutMs(Optional.empty()));
    Assertions.assertFalse(value.getTimeoutMsValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.timeoutMs(Optional.of(vo)));
    Assertions.assertSame(vo, value.getTimeoutMsValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of timeout ms of observed probe against the original")
  void test_timeout_ms_value_holder_read() {
    Object holder = new Object();
    TimeoutMsValueHolder<Object> value = new TimeoutMsValueHolder<>(holder);
    TimeoutMsVO vo = TimeoutMsVO.from(1);
    TimeoutMsVO other = TimeoutMsVO.from(1);
    ObservedProbe original = Mockito.mock(ObservedProbe.class);
    Mockito.when(original.getTimeoutMsValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readTimeoutMs(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readTimeoutMs(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.timeoutMs(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readTimeoutMs(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readTimeoutMs(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of timeout ms of observed probe")
  void test_timeout_ms_value_holder_unset() {
    Object holder = new Object();
    TimeoutMsValueHolder<Object> value = new TimeoutMsValueHolder<>(holder);
    TimeoutMsVO vo = TimeoutMsVO.from(1);
    value.timeoutMs(vo);
    Assertions.assertSame(holder, value.unsetTimeoutMsIfMatches("timeoutMs_other"));
    Assertions.assertTrue(value.getTimeoutMsValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetTimeoutMsIfMatches("timeoutMs"));
    Assertions.assertFalse(value.getTimeoutMsValue().isPresent(),
        "The field name must clear the value");
    value.timeoutMs(vo);
    Assertions.assertSame(holder, value.unsetTimeoutMs());
    Assertions.assertFalse(value.getTimeoutMsValue().isPresent(), "Unset must clear the value");
  }
}
